<script setup>
defineProps({modelValue:String});const emit=defineEmits(['update:modelValue']);
function key(e){if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const value=e.key==='Home'?'grid':e.key==='End'?'list':e.currentTarget.dataset.value==='grid'?'list':'grid';emit('update:modelValue',value);e.currentTarget.parentElement.querySelector('[data-value="'+value+'"]').focus();}}
</script>
<template><div class="library-view-toggle" role="radiogroup" aria-label="Vista de productos"><button v-for="v in ['grid','list']" :key="v" type="button" role="radio" :data-value="v" :aria-checked="modelValue===v" :aria-label="v==='grid'?'Cuadros':'Lista'" :title="v==='grid'?'Cuadros':'Lista'" :tabindex="modelValue===v?0:-1" @click="emit('update:modelValue',v)" @keydown="key"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><g v-if="v==='grid'"><rect x="3" y="3" width="5" height="5" rx="1"/><rect x="12" y="3" width="5" height="5" rx="1"/><rect x="3" y="12" width="5" height="5" rx="1"/><rect x="12" y="12" width="5" height="5" rx="1"/></g><path v-else d="M3 5h2m3 0h9M3 10h2m3 0h9M3 15h2m3 0h9"/></svg></button></div></template>